/* Read sprite geometry without changing source pixels or skin files. */
'use strict';
(function(root){
const P=root.DCPreview,rad=n=>n*Math.PI/180,points=[[-140.5,-247.5],[-282,0],[-140.5,247.5],[142.5,-247.5],[283,0],[142.5,247.5]];
async function pixels(skin,name){const f=await skin.frame(name);if(!f||typeof document==='undefined')return null;let canvas=f.canvas;if(!canvas.getContext){canvas=document.createElement('canvas');canvas.width=f.w;canvas.height=f.h;canvas.getContext('2d').drawImage(f.canvas,0,0);}const data=canvas.getContext('2d').getImageData(0,0,f.w,f.h).data,left=(f.sw-f.w)/2+f.ox,top=(f.sh-f.h)/2-f.oy;function strength(x,y){const sx=x-left-.5,sy=y-top-.5;if(sx<0||sy<0||sx>=f.w-1||sy>=f.h-1)return 0;const x0=Math.floor(sx),y0=Math.floor(sy),fx=sx-x0,fy=sy-y0;let value=0;for(let j=0;j<2;j++)for(let i=0;i<2;i++){const at=((y0+j)*f.w+x0+i)*4,alpha=data[at+3]/255,light=(data[at]+data[at+1]+data[at+2])/3;value+=light*alpha*(i?fx:1-fx)*(j?fy:1-fy);}return value;}return{...f,strength,data,left,top};}
function ridge(sample,min,max,step){let best=0;const samples=[];for(let x=min;x<=max;x+=step){const value=sample(x);samples.push([x,value]);best=Math.max(best,value);}if(best<8||best-Math.min(...samples.map(s=>s[1]))<Math.max(4,best*.05))return null;let sum=0,weight=0;for(const[x,v]of samples)if(v>=best*.99){sum+=x*v;weight+=v;}return weight?{value:sum/weight,strength:best}:null;}
async function calibrateSkin(skin){skin.previewAlignment=null;try{const cache=new Map(),read=async name=>{if(!cache.has(name))cache.set(name,await pixels(skin,name));return cache.get(name);};const cfg=skin.config('_bg'),bg=await read(cfg.tex||'bg-0.png');if(!bg)return;const size=P.pair(cfg.size,[654.5,709.1]),origin=skin.position('_bg',[0,0]),angle=rad(Number(cfg.rotate)||0),cos=Math.cos(-angle),sin=Math.sin(-angle),sample=(x,y)=>{const dx=x-origin[0],dy=y-origin[1],u=dx*cos-dy*sin,v=dx*sin+dy*cos;return bg.strength(bg.sw/2+u*bg.sw/size[0],bg.sh/2+v*bg.sh/size[1]);},boundary=[],normals=[];for(let i=0;i<6;i++){const declared=skin.position('note-'+(i+1),points[i],'pos2'),dx=declared[0]-origin[0],dy=declared[1]-origin[1],radius=Math.hypot(dx,dy);if(radius<20)return;const nx=dx/radius,ny=dy/radius,offsets=[-24,-18,18,24],results=offsets.map(t=>ridge(r=>sample(origin[0]+nx*r-ny*t,origin[1]+ny*r+nx*t),radius*.92,radius*1.08,.12));if(results.some(r=>!r||r.strength<20))return;const value=results.reduce((sum,r)=>sum+r.value,0)/results.length,slope=results.reduce((sum,r,j)=>sum+offsets[j]*r.value,0)/offsets.reduce((sum,t)=>sum+t*t,0),px=nx+slope*ny,py=ny-slope*nx,length=Math.hypot(px,py);boundary.push([origin[0]+nx*value,origin[1]+ny*value]);normals.push([px/length,py/length]);}
const effectRidges={};for(let lane=1;lane<=6;lane++){const hit=skin.config('hit-'+lane);for(const field of ['frame','frame2','frame3']){const name=skin.animationFrame(hit[field],0);if(!name||Object.hasOwn(effectRidges,name))continue;const f=await read(name);if(!f)continue;const found=[.32,.36,.64,.68].map(y=>ridge(x=>f.strength(x,f.sh*y),Math.max(0,(f.sw-f.w)/2+f.ox),Math.min(f.sw,(f.sw+f.w)/2+f.ox),1));if(found.some(x=>!x))continue;const xs=found.map(x=>x.value),average=xs.reduce((a,b)=>a+b,0)/xs.length,offset=(average-f.sw/2)/f.sw;if(Math.max(...xs)-Math.min(...xs)<f.sw*.014&&Math.abs(offset)>.003&&Math.abs(offset)<.2)effectRidges[name]=offset;}}
const noteInsets=[];for(let lane=1;lane<=6;lane++){const note=skin.config('note-'+lane),size=P.pair(note.size,[52.8,52.8]),point=boundary[lane-1],dx=point[0]-origin[0],dy=point[1]-origin[1],r=Math.hypot(dx,dy),normal=normals[lane-1]||[dx/r,dy/r],supports={};for(const [key,tex]of [['normal',note.tex||'guangbiaoa.png'],['multi',note.tex4||note.tex||'guangbiaob.png']]){const f=await read(tex);let support=0;if(f)for(let y=0;y<f.h;y++)for(let x=0;x<f.w;x++){if(f.data[(y*f.w+x)*4+3]<64)continue;const px=((x+f.left+.5)/f.sw-.5)*size[0],py=((y+f.top+.5)/f.sh-.5)*size[1];support=Math.max(support,px*normal[0]+py*normal[1]);}supports[key]=support>0?support:size[0]/2;}noteInsets.push(supports);}skin.previewAlignment={version:1,boundary,normals,effectRidges,noteInsets,origin};}catch{skin.previewAlignment=null;}}
P.calibrateSkin=calibrateSkin;
})(typeof window==='undefined'?globalThis:window);
